contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint256 mintedAmount) public {
        require(mintedAmount > 0);
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;
        bool frozen = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        require(frozen);
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.mintToken(address(this), mintedAmount); if (__ESBMC_reverted()) return;
        assert(
            c.balanceOf(address(this)) == balBefore + mintedAmount &&
            c.totalSupply() == supplyBefore + mintedAmount
        );
    }
}

