pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 mintedAmount) internal {
        vm.assume(mintedAmount > 0);
        try c.freezeAccount(address(this), true) {} catch { return; }
        bool frozen;
        try c.frozenAccount(address(this)) returns (bool __r) { frozen = __r; } catch { return; }
        vm.assume(frozen);
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        try c.mintToken(address(this), mintedAmount) {} catch { return; }
        assertTrue(c.balanceOf(address(this)) == balBefore + mintedAmount &&
            c.totalSupply() == supplyBefore + mintedAmount);
    }

    function testFuzz_run(uint256 mintedAmount) public {
        _run(mintedAmount);
    }

    receive() external payable {}
}
